package ai.applypilot.resume;
import org.springframework.beans.factory.annotation.Value; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile; import org.springframework.web.server.ResponseStatusException; import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.beans.factory.annotation.Autowired;
import ai.applypilot.certifications.CertificationVaultService;
import java.nio.file.*; import java.security.MessageDigest; import java.time.Duration; import java.net.http.HttpClient; import java.util.*; import java.util.Map; import java.util.ArrayList;
@Service public class ResumeService {
 private static final org.slf4j.Logger log=org.slf4j.LoggerFactory.getLogger(ResumeService.class);
 private final ResumeRepository resumes; private final ResumeVersionRepository versions; private final Path root; private final String workerUrl; private final ObjectMapper mapper; private final HttpClient workerClient; private final int workerRequestTimeoutSeconds;
 private final CertificationVaultService certificationVault;
 @Autowired public ResumeService(ResumeRepository r,ResumeVersionRepository v,@Value("${app.upload-dir}") String dir,@Value("${app.worker-url}") String workerUrl,@Value("${app.worker-connect-timeout-seconds:3}") int workerConnectTimeoutSeconds,@Value("${app.worker-request-timeout-seconds:45}") int workerRequestTimeoutSeconds,ObjectMapper mapper,CertificationVaultService certificationVault){resumes=r;versions=v;root=Paths.get(dir).toAbsolutePath().normalize();this.workerUrl=workerUrl;this.mapper=mapper;this.workerRequestTimeoutSeconds=Math.max(1,workerRequestTimeoutSeconds);this.workerClient=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(Math.max(1,workerConnectTimeoutSeconds))).build();this.certificationVault=certificationVault;}
 ResumeService(ResumeRepository r,ResumeVersionRepository v,String dir,String workerUrl,ObjectMapper mapper){this(r,v,dir,workerUrl,3,45,mapper,null);}
 @Transactional public ResumeEntity upload(UUID owner,MultipartFile file){
  String name=Paths.get(Objects.requireNonNullElse(file.getOriginalFilename(),"resume")).getFileName().toString();String lower=name.toLowerCase(Locale.ROOT);
  if(file.isEmpty()||file.getSize()>8L*1024*1024||!(lower.endsWith(".pdf")||lower.endsWith(".docx")))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Upload a PDF or DOCX file up to 8 MB");
  try{byte[] data=file.getBytes();boolean valid=lower.endsWith(".pdf")?data.length>4&&new String(data,0,5,java.nio.charset.StandardCharsets.US_ASCII).startsWith("%PDF-"):data.length>4&&data[0]=='P'&&data[1]=='K';if(!valid)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"File content does not match its extension");
   String hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(data));String key=owner+"/"+UUID.randomUUID()+"/original"+(lower.endsWith(".pdf")?".pdf":".docx");Path target=root.resolve(key).normalize();if(!target.startsWith(root))throw new IllegalStateException("Invalid storage path");Files.createDirectories(target.getParent());Files.write(target,data,StandardOpenOption.CREATE_NEW);
   var saved=resumes.save(new ResumeEntity(owner,name,key,hash,lower.endsWith(".pdf")?"application/pdf":"application/vnd.openxmlformats-officedocument.wordprocessingml.document",data.length));var version=new ResumeVersionEntity(saved.getId(),1,key,hash);versions.save(version);parseInto(version,data,name);return saved;
  }catch(ResponseStatusException e){throw e;}catch(Exception e){throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR,"Could not store resume");}
 }
 private void parseInto(ResumeVersionEntity version,byte[] data,String filename){
  try{String safeName=java.net.URLEncoder.encode(filename,java.nio.charset.StandardCharsets.UTF_8);var uri=java.net.URI.create(workerUrl+"/v1/resumes/parse-raw?filename="+safeName);var request=java.net.http.HttpRequest.newBuilder(uri).timeout(Duration.ofSeconds(workerRequestTimeoutSeconds)).version(java.net.http.HttpClient.Version.HTTP_1_1).header("Content-Type","application/octet-stream").POST(java.net.http.HttpRequest.BodyPublishers.ofByteArray(data)).build();var response=workerClient.send(request,java.net.http.HttpResponse.BodyHandlers.ofString());if(response.statusCode()<200||response.statusCode()>=300)throw new IllegalStateException("Document worker returned HTTP "+response.statusCode());var parsed=mapper.readValue(response.body(),ParsedResume.class);
   if(parsed!=null)version.applyParsed(parsed.extractedText(),parsed.structuredData(),new ArrayList<>(parsed.evidence()));versions.save(version);
  }catch(org.springframework.web.client.RestClientResponseException e){log.warn("Resume parsing service returned HTTP {}",e.getStatusCode().value());}
   catch(Exception e){log.warn("Resume parsing did not complete; original remains available");}
 }
 public record ParsedResume(String extractedText,Map<String,Object> structuredData,List<Object> evidence){}
 @Transactional public VersionDto saveReview(UUID owner,UUID id,int sourceNumber,ResumeReview review){resumes.findByIdAndUserId(id,owner).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));var source=versions.findByResumeIdAndVersionNumber(id,sourceNumber).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));int number=versions.findFirstByResumeIdOrderByVersionNumberDesc(id).map(v->v.getVersionNumber()+1).orElse(1);var version=new ResumeVersionEntity(id,number,source.getStorageKey(),source.getSha256());version.applyParsed(review.extractedText(),review.structuredData(),new ArrayList<>(review.evidence()));versions.save(version);return VersionDto.from(version);}
 @Transactional public VersionDto tailor(UUID owner,UUID id,int sourceVersion,TailorRequest req){
  resumes.findByIdAndUserId(id,owner).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));
  var source=versions.findByResumeIdAndVersionNumber(id,sourceVersion).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));
  if(source.getExtractedText()==null||source.getExtractedText().isBlank())throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"This version has no extracted text to tailor");
  String tailored=TailoringEngine.tailor(source.getExtractedText(),req.jobDescription(),req.targetRole());
  var matchedKeywords=TailoringEngine.extractKeywords(req.jobDescription());
  int next=versions.findFirstByResumeIdOrderByVersionNumberDesc(id).map(v->v.getVersionNumber()+1).orElse(1);
  var newVersion=new ResumeVersionEntity(id,next,source.getStorageKey(),source.getSha256());
  var data=new java.util.HashMap<String,Object>(source.getStructuredData()!=null?source.getStructuredData():Map.of());
  data.put("tailored",true);data.put("targetRole",req.targetRole());data.put("matchedKeywords",matchedKeywords);
  newVersion.applyParsed(tailored,data,source.getEvidence()!=null?new ArrayList<>(source.getEvidence()):new ArrayList<>());
  versions.save(newVersion);return VersionDto.from(newVersion);
 }
 @Transactional public VersionDto export(UUID owner,UUID id,int sourceVersion,String format){return export(owner,id,sourceVersion,format,List.of());}
 @Transactional public VersionDto export(UUID owner,UUID id,int sourceVersion,String format,List<UUID> certificationIds){
  var resume=resumes.findByIdAndUserId(id,owner).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));
  if(!format.equals("pdf")&&!format.equals("docx"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Export format must be pdf or docx");
  var source=versions.findByResumeIdAndVersionNumber(id,sourceVersion).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));
  if(source.getExtractedText()==null||source.getExtractedText().isBlank())throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"This version has no extracted text to export");
  try{var selected=certificationVault==null?new CertificationVaultService.Selected(List.of(),List.of(),List.of()):certificationVault.selected(owner,certificationIds);String exportText=source.getExtractedText();if(!selected.resumeLines().isEmpty())exportText=exportText+"\n\nCERTIFICATIONS\n"+String.join("\n",selected.resumeLines());String body=mapper.writeValueAsString(Map.of("extractedText",exportText));String query=java.net.URLEncoder.encode(format,java.nio.charset.StandardCharsets.UTF_8);var request=java.net.http.HttpRequest.newBuilder(java.net.URI.create(workerUrl+"/v1/resumes/export?format="+query)).version(java.net.http.HttpClient.Version.HTTP_1_1).header("Content-Type","application/json").POST(java.net.http.HttpRequest.BodyPublishers.ofString(body)).build();var response=java.net.http.HttpClient.newHttpClient().send(request,java.net.http.HttpResponse.BodyHandlers.ofByteArray());if(response.statusCode()<200||response.statusCode()>=300)throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"Document export failed");byte[] bytes=response.body();String hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));int next=versions.findFirstByResumeIdOrderByVersionNumberDesc(id).map(v->v.getVersionNumber()+1).orElse(1);String key=owner+"/"+id+"/export-v"+next+"."+format;Path target=root.resolve(key).normalize();if(!target.startsWith(root))throw new IllegalStateException("Invalid storage path");Files.createDirectories(target.getParent());Files.write(target,bytes,StandardOpenOption.CREATE_NEW);var version=new ResumeVersionEntity(id,next,key,hash);var structured=new java.util.HashMap<String,Object>(source.getStructuredData()!=null?source.getStructuredData():Map.of());if(!selected.snapshot().isEmpty())structured.put("certificationsSnapshot",selected.snapshot());var evidence=new ArrayList<Object>();if(source.getEvidence()!=null)evidence.addAll(source.getEvidence());evidence.addAll(selected.evidence());version.applyParsed(exportText,structured,evidence);versions.save(version);return VersionDto.from(version);
  }catch(ResponseStatusException e){throw e;}catch(Exception e){throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR,"Could not export resume");}
 }
 @Transactional(readOnly=true) public Download downloadVersion(UUID owner,UUID id,int number){resumes.findByIdAndUserId(id,owner).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));var v=versions.findByResumeIdAndVersionNumber(id,number).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));try{return new Download(Files.readAllBytes(safeStoredFile(v.getStorageKey())),v.getStorageKey().substring(v.getStorageKey().lastIndexOf('.')+1));}catch(Exception e){throw new ResponseStatusException(HttpStatus.NOT_FOUND);}}
 @Transactional(readOnly=true) public List<VersionDto> versions(UUID owner,UUID id){resumes.findByIdAndUserId(id,owner).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));return versions.findAllByResumeIdOrderByVersionNumberDesc(id).stream().map(VersionDto::from).toList();}
 @Transactional(readOnly=true) public List<ResumeDto> list(UUID owner){return resumes.findAllByUserIdOrderByCreatedAtDesc(owner).stream().map(ResumeDto::from).toList();}
 @Transactional(readOnly=true) public byte[] download(UUID owner,UUID id){var r=resumes.findByIdAndUserId(id,owner).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));try{return Files.readAllBytes(safeStoredFile(r.getStorageKey()));}catch(Exception e){throw new ResponseStatusException(HttpStatus.NOT_FOUND);}}
 private Path safeStoredFile(String key)throws java.io.IOException{Path candidate=root.resolve(key).normalize();if(!candidate.startsWith(root))throw new java.io.IOException("Stored file is outside upload root");Path realRoot=root.toRealPath();Path realFile=candidate.toRealPath();if(!realFile.startsWith(realRoot))throw new java.io.IOException("Stored file resolves outside upload root");return realFile;}
 public record ResumeDto(UUID id,String filename,String sha256,long size,java.time.Instant createdAt){static ResumeDto from(ResumeEntity r){return new ResumeDto(r.getId(),r.getFilename(),r.getSha256(),r.getSize(),r.getCreatedAt());}}
 public record VersionDto(int version,String sha256,String extractedText,Map<String,Object> structuredData,List<Object> evidence,java.time.Instant createdAt){static VersionDto from(ResumeVersionEntity v){return new VersionDto(v.getVersionNumber(),v.getSha256(),v.getExtractedText(),v.getStructuredData(),v.getEvidence(),v.getCreatedAt());}}
 public record ResumeReview(@jakarta.validation.constraints.NotBlank @jakarta.validation.constraints.Size(max=100000) String extractedText,@jakarta.validation.constraints.NotNull Map<String,Object> structuredData,@jakarta.validation.constraints.NotNull List<Object> evidence){}
 public record Download(byte[] bytes,String extension){}
}
